    string out;
    for (long long k = 0; k < q; k++) {
        long long kind = ops[k][0], x = ops[k][1], y = ops[k][2], z = ops[k][3];
        if (kind == 1) {
            bitAdd(d, x, z);
            bitAdd(d, y + 1, -z);
